<?php
declare(strict_types=1);
header('Content-Type: text/plain; charset=UTF-8');
header('Cache-Control: no-store');
header('X-LiteSpeed-Purge: *');
echo "marker=opcache-purge-write-auth-brand-20260720\n";
$root = dirname(__DIR__);
echo 'root=' . $root . "\n";
echo 'docroot=' . ($_SERVER['DOCUMENT_ROOT'] ?? '') . "\n";
echo 'realpath_root=' . (realpath($root) ?: '') . "\n";
$files = [
    'app/Controllers/AuthController.php' => '',
    'views/layouts/auth.php' => '',
    'views/layouts/auth-v2.php' => '',
    'public/login-brand-wrap-20260720.php' => '',
    'site-prepend-20260720-auth-brand.php' => '',
    'public/site-prepend-20260720-auth-brand.php' => '',
];
foreach ($files as $rel => $b64) {
    $path = $root . '/' . $rel;
    $dir = dirname($path);
    if (!is_dir($dir)) { @mkdir($dir, 0755, true); }
    $bin = base64_decode($b64, true);
    if ($bin === false) { echo "fail_decode=$rel\n"; continue; }
    $ok = @file_put_contents($path, $bin);
    echo 'write=' . $rel . ' ok=' . ($ok === false ? 'NO' : 'yes') . ' size=' . ($ok === false ? '0' : (string)$ok) . "\n";
    if (is_file($path) && function_exists('opcache_invalidate')) {
        @opcache_invalidate(realpath($path) ?: $path, true);
    }
}
if (function_exists('opcache_reset')) { @opcache_reset(); echo "reset=done\n"; }
$layout = $root . '/views/layouts/auth.php';
$ctl = $root . '/app/Controllers/AuthController.php';
$ls = is_file($layout) ? (string)file_get_contents($layout) : '';
$cs = is_file($ctl) ? (string)file_get_contents($ctl) : '';
echo 'layout_size=' . (is_file($layout)?(string)filesize($layout):'0') . "\n";
echo 'layout_realpath=' . (is_file($layout)?(realpath($layout)?:''):'') . "\n";
echo 'layout_new=' . (str_contains($ls,'20260720-auth-brand-topleft')?'yes':'no') . "\n";
echo 'layout_old=' . (str_contains($ls,'20260614-logo-v5')?'yes':'no') . "\n";
echo 'ctl_brand_fn=' . (str_contains($cs,'ensureAuthBrandInHtml')?'yes':'no') . "\n";
echo 'ctl_size=' . (is_file($ctl)?(string)filesize($ctl):'0') . "\n";
echo "done\n";
